"use strict";(self.webpackChunkeleven_plus_core_concepts=self.webpackChunkeleven_plus_core_concepts||[]).push([[5742],{5742:e=>{e.exports=JSON.parse('{"concept":"Letters-to-Numbers Puzzles","subject":"mathematics","category":"Combinatorics & Counting","explanation":"In these puzzles, each letter represents a unique digit (0-9). Common examples: SEND + MORE = MONEY or FACE has 4 letters = 4 different digits. Use logic: if two letters add to give another letter, work out constraints. Often the first letter can\'t be 0. These test systematic thinking and constraint solving.","examples":[{"question":"In the word FACE, each letter is a different digit. If F + A + C + E = 20, and F = 8, what could A + C + E equal?","solution":"12","explanation":"If F = 8 and F + A + C + E = 20, then A + C + E = 20 - 8 = 12."},{"question":"CAB \xd7 2 = DEED. What digit does C represent?","solution":"C = 5","explanation":"CAB \xd7 2 gives a 4-digit number DEED where D appears twice. Try systematically: if C = 5, then 5AB \xd7 2 = 1110 to 1998, which could give DEED pattern like 1221."},{"question":"ABC + CBA = 1111. All letters are different digits. What is A + B + C?","solution":"16","explanation":"ABC + CBA = (100A + 10B + C) + (100C + 10B + A) = 101A + 20B + 101C = 101(A + C) + 20B = 1111. So 101(A + C) = 1111 - 20B. Since 1111 = 101 \xd7 11, we get A + C = 11 - 20B/101. Trying B = 0: A + C = 11, so A + B + C = 11 + 0 = 11. But let\'s check: if A = 5, C = 6, B = 0: 506 + 605 = 1111 \u2713"}],"exercises":[{"type":"multiple-choice","question":"In AB + BA = 121, where A and B are different digits, what is A \xd7 B?","options":["20","24","30","56"],"correct":[0],"explanation":"AB + BA = (10A + B) + (10B + A) = 11A + 11B = 11(A + B) = 121. So A + B = 11. Possible pairs: (2,9), (3,8), (4,7), (5,6). Products: 18, 24, 28, 30. Wait, let me recalculate: if A + B = 11, then A \xd7 B could be 2\xd79=18, 3\xd78=24, 4\xd77=28, 5\xd76=30. None match exactly, so let me check 121/11 = 11, so A + B = 11. If A=4, B=7: 47+74=121 \u2713. So A\xd7B = 28. Hmm, that\'s not an option. Let me try A=5, B=6: 56+65=121 \u2713. A\xd7B = 30."},{"type":"multiple-choice","question":"LEAD has 4 different digits. If L = 1 and D = 8, and LEAD is a 4-digit number, which is NOT possible for E?","options":["0","2","7","9"],"correct":[0],"explanation":"If L = 1 and D = 8, then LEAD = 1EA8. Since all digits must be different, E cannot be 1 or 8. Also, A cannot be 1, 8, or E. From the options: 0, 2, 7, 9 are all possible for E."},{"type":"open-ended","question":"In HI + BYE = LUCK, each letter represents a different digit. If H = 1 and L = 1, explain why this is impossible.","sample_answer":"If H = 1 and L = 1, then two letters represent the same digit, which violates the rule that each letter must represent a different digit.","explanation":"The fundamental rule is that each letter represents a unique digit."}],"tips":["Each letter = unique digit (usually 0-9)","Leading digits usually can\'t be 0","Look for patterns: repeated letters give clues","Try small values first, work systematically","Check your answer by substituting back"]}')}}]);